const staticData = $getWorkflowStaticData('global');
if (!staticData.agentContext) staticData.agentContext = {};
const sessionId = $json.body.session_id || $json.query.session_id || 'default_session';
staticData.agentContext[sessionId] = $json.headers.authorization || '';
return [{ json: $json }];

const agentOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
let message = agentOutput;
let finalData = [];

const cacheRegex = /Mã Ngăn Kéo:\s*([a-zA-Z0-9_\-]+)/i;
const match = message.match(cacheRegex);

if (match) {
    const cacheId = match[1];
    const staticData = $getWorkflowStaticData('global');
    if (staticData.dataCache && staticData.dataCache[cacheId]) {
        finalData = staticData.dataCache[cacheId].data;
        delete staticData.dataCache[cacheId];
    } else if (staticData[cacheId]) {
        finalData = staticData[cacheId];
        delete staticData[cacheId];
    }
    message = message.replace(match[0], '').trim();
    if (!finalData || finalData.length === 0) {
        return [{
            json: {
                status: "error",
                message: "Hệ thống đang quá tải hoặc dữ liệu đã hết hạn. Xin vui lòng đặt lại câu hỏi.",
                data: []
            }
        }];
    }
}

return [{
    json: {
        status: "success",
        message: message.trim(),
        data: finalData
    }
}];
